/**
 * Builds dev/test-bundle.js for browser-testing the content script on the real
 * LinkedIn DOM (no extension load required — the page context gets the same
 * code plus a `chrome` shim that runs the mock provider through the real
 * heuristics + verdict pipeline).
 *
 *   node dev/build-test-bundle.mjs
 *
 * Injected via Playwright `addScriptTag({ content })` on linkedin.com.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => readFileSync(join(root, p), 'utf8');

/** Our libs are simple modules — strip ESM syntax for concatenation. */
const stripModuleSyntax = (src) =>
  src.replace(/^import[^;]+;$/gm, '').replace(/^export\s+/gm, '');

const questions = stripModuleSyntax(read('lib/questions.js'));
const heuristics = stripModuleSyntax(read('lib/heuristics.js'));
const verdict = stripModuleSyntax(read('lib/verdict.js'));
const content = read('content/content.js');

const teardown = `
// --- teardown any previous injection ---
try {
  if (typeof window.__larpTeardown === 'function') window.__larpTeardown();
  window.__larpDetectorLoaded = false;
  window.__larpDebug = undefined;
  document.querySelectorAll('.larp-badge').forEach((b) => b.remove());
  document
    .querySelectorAll('[data-larp-observed]')
    .forEach((el) => delete el.dataset.larpObserved);
} catch {}
`;

const shim = `
// --- test chrome shim: mock provider wired to the real heuristics + verdict ---
window.__larpTestLog = [];
const __testSettings = {
  enabled: true,
  showGenuine: true,
  sensitivity: 1.5,
  provider: 'mock',
  apiKey: '',
  openrouterApiKey: '',
  model: '',
};
window.chrome = {
  runtime: {
    id: 'test-shim',
    lastError: undefined,
    getURL: (p) => p,
    sendMessage: (msg, cb) => {
      if (msg.type === 'GET_SETTINGS') {
        setTimeout(() => cb({ ok: true, settings: __testSettings }), 10);
        return;
      }
      if (msg.type === 'ANALYZE_POST') {
        // Simulated latency so the "checking for larp…" state is exercised.
        setTimeout(() => {
          const r = analyzeHeuristically(msg.post);
          const v = r
            ? composeVerdict(r.answers, { model: r.model, usage: r.usage, source: 'test-shim' })
            : null;
          const show = v ? shouldShow(v, __testSettings) : false;
          window.__larpTestLog.push({
            urn: msg.post.urn,
            text: String(msg.post.post_text || '').slice(0, 90),
            headline: String(msg.post.author_headline || '').slice(0, 60),
            label: v ? v.label : null,
            pct: v ? v.pct : null,
            score: v ? v.score : null,
            show,
          });
          cb({ ok: true, verdict: v, show });
        }, 150);
        return;
      }
      setTimeout(() => cb({ ok: false, error: 'unknown message type ' + msg.type }), 0);
    },
  },
  storage: { onChanged: { addListener: () => {} } },
};
`;

writeFileSync(
  join(root, 'dev/test-bundle.js'),
  [
    '/* GENERATED by dev/build-test-bundle.mjs — do not edit. */',
    '(() => {',
    teardown,
    shim,
    '// ===== lib/questions.js =====',
    questions,
    '// ===== lib/heuristics.js =====',
    heuristics,
    '// ===== lib/verdict.js =====',
    verdict,
    '// ===== content/content.js =====',
    content,
    '})();',
  ].join('\n\n')
);

console.log('wrote dev/test-bundle.js');
